import type { SaintRec } from "./types";

export const M01: SaintRec[] = [
  { key: "01-01", name: "Мч. Вонифатия Тарсийского", kind: "saint", desc: "Святой мученик Вонифатий был рабом богатой молодой римлянки Аглаиды и состоял с ней в беззаконном сожительстве. Но оба они чувствовали угрызения совести и хотели как-то омыть свой грех." },
  { key: "01-01", name: "Прп. Илии Муромца, Печерского, в Ближних пещерах", kind: "saint", desc: "Преподобный Илия Муромец, Печерский, в Ближних пещерах, был родом из Мурома, подвизался в Киево-Печерской обители и скончался около 1188 г. Преподобный Илия почивает в молитвенном положении: «три первые персты соединены вместе и протянуты, а два последние, безымянный и мизинец, пригнуты к ладони." },
  { key: "01-01", name: "свт. Вонифатия Милостивого, епископа Ферентийского", kind: "saint", desc: "Святой Вонифатий Милостивый, епископ Ферентийский, жил в Италии в VI веке. Сын бедной вдовы, он с детства проявлял черты любви к ближнему, доходившей до самоотвержения." },
  { key: "01-01", name: "свт. Григория, епископа Омиритского", kind: "saint", desc: "Святитель Григорий, епископ Омиритский, сын Агапия и Феодотии, от юности был исполнен благодати Божией и имел дар исцелений и чудотворений. Промысл Божий вел его к святительскому служению." },
  { key: "01-02", name: "Предпразднство Рождества Христова", kind: "feast", desc: "О событиях праздника Рождества Христова повествуют два евангелиста-синоптика: апостолы Матфей и Лука, причем их рассказы отличаются друг от друга. Конечно, в этом отличии видится особенная ценность каждого повествования, ибо евангелисты взаимно дополняют друг друга и каждый сообщает сведения, не упоминаемые другим." },
  { key: "01-02", name: "Сщмч. Игнатия Богоносца, епископа Антиохийского", kind: "saint", desc: "Святой Игнатий Богоносец имеет особое значение для нас, потому что он близко общался с апостолами, непосредственно от них слышал христианское учение и был свидетелем распространения и развития первых христианских общин." },
  { key: "01-02", name: "свт. Антония (Смирницкого), архиепископа Воронежского", kind: "saint", desc: "Архиепископ Антоний (Смирницкий Авраамий Гаврилович) родился 29 октября 1773 года в селе Повстино Пирятинского уезда Полтавской губернии в день преподобного Авраамия Ростовского (в Крещении получил его святое имя) и был старшим сыном в многодетной семье протоиерея." },
  { key: "01-02", name: "св. прав. Иоанна Кронштадтского", kind: "saint", desc: "Св. прав. Иоанн Кронштадтский (1829-1908) — великий пастырь и чудотворец. Сын бедного сельского дьячка из Архангельской губернии, с детства проявлял особую религиозность.", lifeId: "ioann-kronstadt" },
  { key: "01-02", name: "Прп. Игнатия, архимандрита Печерского, в Дальних пещерах", kind: "saint", desc: "Преподобный Игнатий от юности соблюдал себя в чистоте и непорочности. Принявши на себя иноческий чин, святой своей жизнью, кротостью и любовью ко всем он обратил на себя взоры всех." },
  { key: "01-02", name: "свт. Филогония, епископа Антиохийского", kind: "saint", desc: "Святитель Филогоний, епископ Антиохийский, до поставления на епископскую кафедру был адвокатом, выступал в защиту нищих, вдов и сирот. Когда он овдовел, его избрали епископом Антиохии." },
  { key: "01-02", name: "свт. Даниила II, архиепископа Сербского", kind: "saint", desc: "Свт. Даниил II, архиепископ Сербский (XIII–XIV вв.). Выходец из знатного рода, в юности тайно покинул королевский двор и принял монашество. Прославился аскетизмом, был игуменом Хиландарского монастыря на Афоне, затем епископом Холмским." },
  { key: "01-02", name: "Сщмч. Николая Чернышева, пресвитера", kind: "saint", desc: "Протоиерей Николай Чернышев с 1914 года и до своей гибели был благочинным Воткинской и Галевской волостей на территории современной Удмуртии. За безупречную службу Православной Церкви неоднократно награждался епархиальным начальством." },
  { key: "01-02", name: "мц. Варвары Чернышевой", kind: "saint", desc: "Протоиерей Николай Чернышев с 1914 года и до своей гибели был благочинным Воткинской и Галевской волостей на территории современной Удмуртии. За безупречную службу Православной Церкви неоднократно награждался епархиальным начальством." },
  { key: "01-02", name: "Новодворская", kind: "saint", desc: "Первообраз Новодворской иконы Божией Матери был написан святителем Петром, митрополитом Московским (память 21 декабря), предположительно в 1320 году. Будучи еще иеромонахом монастыря на Волыни и испросив благословение игумена, Петр оставил обитель в поисках уединенного места." },
  { key: "01-02", name: "Спасительница утопающих", kind: "saint", desc: "В восьми верстах от города Новгород-Северска в Черниговской губернии есть село Леньков, расположенное при реке Десне. В глубокой древности это селение было несколько ближе к городу." },
  { key: "01-03", name: "Предпразднство Рождества Христова", kind: "feast", desc: "О событиях праздника Рождества Христова повествуют два евангелиста-синоптика: апостолы Матфей и Лука, причем их рассказы отличаются друг от друга. Конечно, в этом отличии видится особенная ценность каждого повествования, ибо евангелисты взаимно дополняют друг друга и каждый сообщает сведения, не упоминаемые другим." },
  { key: "01-03", name: "Мц. Иулиании и с нею 500 мужей и 130-ти жен, в Никомидии пострадавших", kind: "saint", desc: "Святая мученица Иулиания, дочь знатного язычника Африкана, родилась в г. Никомидии. В девятилетнем возрасте была обручена с неким Елевсием. Обладая глубоким разумом и склонной к добру душой, святая Иулиания поняла призрачность и обман языческой веры." },
  { key: "01-03", name: "свт. Петра Московского, митрополита Киевского, всея Руси чудотворца", kind: "saint", desc: "Свт. Петр Московский, митрополит Киевский и всея Руси, родился на Волыни и с юности посвятил себя монашеству. Прославившись благочестием, в 1308 году был возведен на Русскую митрополию." },
  { key: "01-03", name: "Мц. благоверной княгини Иулиании Вяземской, Новоторжской", kind: "saint", desc: "Блгв. княгиня Иулиания Вяземская (†1406) ‒ супруга князя Симеона Мстиславича, пострадавшая за верность браку. После изгнания из Смоленска жила в Торжке, где князь Юрий Святославич, воспылав страстью, убил её мужа и пытался овладеть ею." },
  { key: "01-03", name: "блж. Прокопия, Христа ради юродивого, Вятского", kind: "saint", desc: "Блаженный Прокопий, Христа ради юродивый, Вятский, сын благочестивых крестьян. Когда Прокопию исполнилось 20 лет, его хотели женить, но он тайно ушел в город Хлынов и принял на себя подвиг юродства." },
  { key: "01-03", name: "свт. Филарета (Амфитеатрова), в схиме Феодосия, митрополита Киевского", kind: "saint", desc: "Святитель Филарет (в миру Феодор) родился 17 апреля 1779 года в селе Высоком Кромского уезда Орловской губернии в семье Георгия Амфитеатрова и был четвертым ребенком из восьми детей." },
  { key: "01-03", name: "мч. Фемистоклея Мирликийского", kind: "saint", desc: "Святой мученик Фемистоклей жил в г. Мирах Ликийских в царствование гонителя христиан Декия (201–251). Фемистоклей был пастухом. Во время гонения он скрыл у себя некоего христианина Диоскорида, а сам вышел к преследователям." },
  { key: "01-03", name: "Сщмч. Михаила Киселева, пресвитера", kind: "saint", desc: "Протоиерей Михаил Киселев родился в 1856 году. Служил в церкви завода Майкора Соликамского уезда Пермской губернии. Был расстрелян большевиками в ночь на 3 января 1919 года." },
  { key: "01-03", name: "сщмч. Сергия Цветкова, диакона", kind: "saint", desc: "Священномученик Сергий родился 5 октября 1884 года в селе Белая Колпь Волоколамского уезда Московской губернии в семье диакона Ивана Глебовича Цветкова и его супруги Елизаветы Алексеевны." },
  { key: "01-03", name: "сщмч. Никиты (Прибыткова), епископа Белевского", kind: "saint", desc: "Епископ Никита (в миру Прибытков Николай Григорьевич) родился на Алтае в селе Елбанки Бийского района (уезда) 6 декабря 1859 года. После окончания Духовной семинарии — он священник на Алтае." },
  { key: "01-03", name: "сщмч. Леонтия Строцюка, диакона", kind: "saint", desc: "Священномученик Леонтий родился в январе 1878 года в селе Сагрынь Грубешовского уезда Люблинской губернии в украинской семье псаломщика Иосифа Строцюка." },
  { key: "01-04", name: "Предпразднство Рождества Христова", kind: "feast", desc: "О событиях праздника Рождества Христова повествуют два евангелиста-синоптика: апостолы Матфей и Лука, причем их рассказы отличаются друг от друга. Конечно, в этом отличии видится особенная ценность каждого повествования, ибо евангелисты взаимно дополняют друг друга и каждый сообщает сведения, не упоминаемые другим." },
  { key: "01-04", name: "Вмц. Анастасии Узорешительницы", kind: "saint", desc: "Святая великомученица Анастасия Узорешительница (&dagger; ок. 304) пострадала во время правления римского императора Диоклитиана (284–305). Родилась в Риме, в семье сенатора Претекстата.", lifeId: "anastasia" },
  { key: "01-04", name: "прп. Никифора Прокаженного, монаха", kind: "saint", desc: "Преподобный Никифор (в миру Николай Джанакакис) родился в селении Сирикари на острове Крит в 1890 году в благочестивой семье. В 13 лет родители отдали его на обучение цирюльнику, жившему в городе Ханья." },
  { key: "01-04", name: "Димитрия Киранова", kind: "saint", desc: "Протоиерей Димитрий Киранов родился в 1879 году в Таврической губернии в семье священника. К тому времени род болгарских священников Кирановых насчитывал уже более 300 лет." },
  { key: "01-04", name: "Феодора Поройкова", kind: "saint", desc: "Священномученик Феодор родился в 1875 году в селе Мимошня Угличского уезда Ярославской губернии в семье священнослужителя. Когда пришло время получать образование, Федор Николаевич поступил в Ярославскую Духовную семинарию, но проучился он там только два курса, а в начале XX века женился и принял священный сан." },
  { key: "01-05", name: "Предпразднство Рождества Христова", kind: "feast", desc: "О событиях праздника Рождества Христова повествуют два евангелиста-синоптика: апостолы Матфей и Лука, причем их рассказы отличаются друг от друга. Конечно, в этом отличии видится особенная ценность каждого повествования, ибо евангелисты взаимно дополняют друг друга и каждый сообщает сведения, не упоминаемые другим." },
  { key: "01-05", name: "Свт. Феоктиста, архиепископа Новгородского", kind: "saint", desc: "По преставлении архиепископа Климента новгородцы с посадником своим Андреем много рассуждали о преемнике его, все, от мала до велика, возлюбили Богом назначенного, мужа смиренного и доброго, игумена Благовещенского монастыря Феоктиста." },
  { key: "01-05", name: "прп. Нифонта, епископа Кипрского", kind: "saint", desc: "Преподобный Нифонт, епископ Кипрский (IV), родился в Пафлагонии, образование получил в Константинополе. В детстве он был кротким и добрым, часто посещал церковную службу." },
  { key: "01-05", name: "прп. Павла, епископа Неокесарийского", kind: "saint", desc: "Преподобный Павел, епископ Неокесарийский, пострадал при императоре Ликинии (307–324). Твердо исповедав на суде свою веру во Христа, святой Павел подвергся побоям." },
  { key: "01-05", name: "равноап. Наума Охридского", kind: "saint", desc: "Равноап. Наум Охридский († 910), ученик свв. Кирилла и Мефодия, вместе со святителем Климентом проповедовал Евангелие славянам. После чудесного освобождения из германского плена основал Архангельский монастырь на Охридском озере, ставший духовным центром." },
  { key: "01-05", name: "Сщмч. Василия Спасского, пресвитера", kind: "saint", desc: "Священномученик Василий Георгиевич Спасский родился в 1878 году в Козьмодемьянском погосте Тверского уезда Тверской губернии в семье священника. По окончании Духовной семинарии был рукоположен во священника, служил в храмах Тверской епархии." },
  { key: "01-05", name: "Макария", kind: "saint", desc: "Преподобномученик Макарий (Миронов) родился в 1878 году в селе Филино Дорогобужского района. 21 декабря 1937 года он был арестован в селе Завидовская Горка Кесовогорского района Калининской области." },
  { key: "01-06", name: "Предпразднство Рождества Христова", kind: "feast", desc: "О событиях праздника Рождества Христова повествуют два евангелиста-синоптика: апостолы Матфей и Лука, причем их рассказы отличаются друг от друга. Конечно, в этом отличии видится особенная ценность каждого повествования, ибо евангелисты взаимно дополняют друг друга и каждый сообщает сведения, не упоминаемые другим." },
  { key: "01-06", name: "Прп. Николая Славянина, схимонаха", kind: "saint", desc: "Преподобный Николай монах был военачальником при византийском царе Никифоре I (802–811). Он был послан на войну с болгарами. Накануне битвы он подвергся искушению от одной женщины, но мужественно ему воспротивился." },
  { key: "01-06", name: "Прмч. Иннокентия (Беды), архимандрита", kind: "saint", desc: "Преподобномученик Иннокентий (Беда) родился в 1881 году в селе Мойсенцы Золотоношского уезда Полтавской губернии в крестьянской семье. Образование получил дома." },
  { key: "01-06", name: "сщмч. Сергия Мечёва, пресвитера", kind: "saint", desc: "Священномученик Сергий родился 17 сентября 1892 года в семье известного московского старца протоиерея Алексия Мечева [1] , настоятеля храма святителя Николая в Кленниках (с 1893 по 1923 год)." },
  { key: "01-07", name: "Рождество Господа Бога и Спаса нашего Иисуса Христа", kind: "feast", desc: "О событиях праздника Рождества Христова повествуют два евангелиста-синоптика: апостолы Матфей и Лука, причем их рассказы отличаются друг от друга. Конечно, в этом отличии видится особенная ценность каждого повествования, ибо евангелисты взаимно дополняют друг друга и каждый сообщает сведения, не упоминаемые другим." },
  { key: "01-07", name: "Преставление сщмч. Леонида Серебренникова, пресвитера", kind: "saint", desc: "Леонид Константинович Серебренников, сын священника Виленской губернии, родился 14 апреля 1894 года. В 1904-1910 годах обучался в Виленском духовном училище." },
  { key: "01-08", name: "Попразднство Рождества Христова", kind: "feast", desc: "О событиях праздника Рождества Христова повествуют два евангелиста-синоптика: апостолы Матфей и Лука, причем их рассказы отличаются друг от друга. Конечно, в этом отличии видится особенная ценность каждого повествования, ибо евангелисты взаимно дополняют друг друга и каждый сообщает сведения, не упоминаемые другим." },
  { key: "01-08", name: "Собор Пресвятой Богородицы", kind: "feast", desc: "Собор Пресвятой Богородицы. На другой день по Рождестве Христове празднуется Собор Пресвятой Богородицы, память святого Иосифа Обручника, царя Давида (предка по плоти Господа Иисуса Христа) и святого Иакова, брата Господня, сына от первого брака святого Иосифа Обручника." },
  { key: "01-08", name: "Сщмч. Евфимия, епископа Сардийского", kind: "saint", desc: "Священномученик Евфимий, епископ Сардийский, в период царствования византийского императора Константина Багрянородного (780–797) и императрицы Ирины (797–802) за свою добродетельную жизнь был избран епископом Сардийским и присутствовал на VII Вселенском Соборе (787), на котором обличал иконоборческую ересь." },
  { key: "01-08", name: "Прп. Константина Синадского (Фригийского)", kind: "saint", desc: "Преподобный Константин Синадский, уроженец г. Синада, по происхождению еврей, с детства чувствовал влечение к христианской вере. Внимательное отношение к учению Христа воспламенило его сердце, и он в ранней юности ушел от родителей в иноческую обитель." },
  { key: "01-08", name: "прп. Евареста Студита", kind: "saint", desc: "Преподобный Еварест, родом из Галатии, сын знатных родителей, с юных лет стремился к иноческой жизни, особенно любил читать книги святого Ефрема Сирина ." },
  { key: "01-08", name: "прп. Никодима Тисманского (1406)", kind: "saint", desc: "Преподобный Никодим Тисманский родился в одной из центральных областей Македонии. Отец его был греком, а мать происходила из Сербии. Преподобный Никодим получил прекрасное образование, знал сербский и греческий языки, был прекрасным переводчиком и писателем." },
  { key: "01-08", name: "Прмч. Исаакия Оптинского (Бобракова), архимандрита", kind: "saint", desc: "Преподобномученик Исаакий Оптинский (в миру Иван Николаевич Бобраков) родился в 1865 году в селе Остров Малоархангельского уезда Орловской губернии в крестьянской семье." },
  { key: "01-08", name: "Николая Тарбеева", kind: "saint", desc: "Иерей Николай Залесский родился 3 мая 1877 года в селе Федоровском (Харбай) Астраханского уезда в семье местного псаломщика Даниила Залесского. Семья их была большой, и жили они бедно, однако отец сумел дать своим детям духовное образование." },
  { key: "01-08", name: "Михаила Чельцова", kind: "saint", desc: "Протоиерей Михаил Чельцов родился 27 мая 1870 года в селе Кикино Ряжского уезда Рязанской губернии, в семье священника Знаменской церкви Павла Михайловича Чельцова и Агриппины Сергеевны (в девичестве Полянская)." },
  { key: "01-08", name: "Леонида (Антощенко), епископа Марийского", kind: "saint", desc: "Епископ Марийский Леонид (в миру Лаврентий Евтихиевич Антощенко) родился 6 августа 1872 года, в праздник Преображения Господня, в деревне Мало-Николаевка Бахмутского уезда Екатеринославской губернии в семье крестьян." },
  { key: "01-08", name: "Александра Крылова, пресвитера", kind: "saint", desc: "Священник Александр Иванович Крылов родился 14 августа 1892 года в селе Ряхово Ковровского уезда Владимирской губернии. Отец его — Крылов Иван Алексеевич — происходил из крестьянской семьи, получил образование в городе Тверь, был учителем в" },
  { key: "01-08", name: "прмч. Василия (Мазуренко), иеромонаха", kind: "saint", desc: "Иеромонах Василий (Мазуренко) родился в 1882 году. О его жизни нам известно крайне мало. Известно лишь, что мученическую кончину он принял в 1938 году на другой день после Рождества Христова, 8 января." },
  { key: "01-08", name: "прмцц. Анфисы", kind: "saint", desc: "Преподобномученица Анфиса (в миру Сысоева Александра Матвеевна) родилась 17 апреля 1868 (1870?) года в селе Ивановское Тульской губернии. С 1878 года подвизалась в Крестовоздвиженском монастыре города Белева." },
  { key: "01-08", name: "Макарии (Сапрыкиной), монахинь", kind: "saint", desc: "Преподобномученица Макария (в миру Сапрыкина Прасковья Афанасьевна) родилась 28 октября 1867 года в селе Теляжье Мало-Архангельского уезда Орловской губернии." },
  { key: "01-09", name: "Попразднство Рождества Христова", kind: "feast", desc: "О событиях праздника Рождества Христова повествуют два евангелиста-синоптика: апостолы Матфей и Лука, причем их рассказы отличаются друг от друга. Конечно, в этом отличии видится особенная ценность каждого повествования, ибо евангелисты взаимно дополняют друг друга и каждый сообщает сведения, не упоминаемые другим." },
  { key: "01-09", name: "Ап. от 70-ти первомч. и архидиакона Стефана", kind: "saint", desc: "Св. архидиакон Стефан, первый христианский мученик, был одним из семи диаконов, избранных апостолами. Проповедуя с дерзновением, он обличал иудеев в отвержении Мессии ‒ Христа.", lifeId: "stephan" },
  { key: "01-09", name: "прп. Феодора Начертанного, исп.", kind: "saint", desc: "Преподобный Феодор исповедник и брат его исповедник Феофан Начертанные родились в Иерусалиме от родителей-христиан. Старшим был Феодор. Он с раннего детства избегал детских забав и любил посещать церковные службы." },
  { key: "01-09", name: "Прп. Вонифатия Феофановского, Киевского, игумена", kind: "saint", desc: "Преподобный Вонифатий (в миру Виноградский Дамиан Федорович) родился в 1785 году в Херсонской губернии Александрийского уезда, в селе Михайловке, от благочестивых родителей Феодора и Евдокии Виноградских." },
  { key: "01-09", name: "свт. Феодора I, архиепископа Константинопольского", kind: "saint", desc: "Святитель Феодор, архиепископ Константинопольский, уроженец Константинополя, вел благочестивую жизнь, был возведен в сан пресвитера и служил в соборе Святой Софии, где был также сосудохранителем." },
  { key: "01-09", name: "Сщмч. Тихона (Никанорова), архиепископа Воронежского", kind: "saint", desc: "Архиепископ Тихон (в миру Василий Никаноров) родился 30 января 1855 года в семье Варсонофия Никанорова в селе Кирюга Новгородской губернии. Уже в детстве проявилась его склонность к созерцательной, уединенной, молитвенной жизни." },
  { key: "01-09", name: "мц. Антонины Брянских", kind: "saint", desc: "Антонина Арсеньевна Брянских родилась в 1891 году в Иркутске в семье мещан. 17 ноября 1937 года она была арестована в Архангельске за то, что «участвовала в тайных богослужениях»." },
  { key: "01-10", name: "Попразднство Рождества Христова", kind: "feast", desc: "О событиях праздника Рождества Христова повествуют два евангелиста-синоптика: апостолы Матфей и Лука, причем их рассказы отличаются друг от друга. Конечно, в этом отличии видится особенная ценность каждого повествования, ибо евангелисты взаимно дополняют друг друга и каждый сообщает сведения, не упоминаемые другим." },
  { key: "01-10", name: "Прп. Игнатия Ломского, Ярославского", kind: "saint", desc: "Обстоятельства его жизни в миру неизвестны. Свой подвижнический путь он начал в Спасо-Прилуцком монастыре, в Вологде, иноческий постриг принял в Кирилло-Белозерском монастыре." },
  { key: "01-10", name: "прп. Корнилия Крыпецкого", kind: "saint", desc: "В двадцати пяти километрах от города Пскова на небольшом островке среди болот и лесов ныне расположен Иоанно-Богословский Крыпецкий монастырь. Его основателем в XV веке стал ученик преподобного Евфросина преподобный Савва, который, оставив " },
  { key: "01-10", name: "ап. от 70-ти Никанора", kind: "saint", desc: "Святые апостолы от 70 Прохор, Никанор, Тимон и Пармен были первыми диаконами Церкви Христовой. В книге Деяний апостолов ( Деян.6:1-6 ) рассказывается, что в Иерусалиме двенадцать апостолов избрали семь мужей: Стефана , Филиппа , Прохора , Н" },
  { key: "01-10", name: "Никодима (Кононова), епископа Белгородского", kind: "saint", desc: "Сщмч. Никодим (Кононов), епископ Белгородский, родился в 1871 году в семье священника. Окончил Санкт-Петербургскую Духовную академию, принял монашество." },
  { key: "01-10", name: "Аркадия Решетникова, диакона", kind: "saint", desc: "Диакон Аркадий Решетников служил в селе Юрлы Чердынского уезда Пермской губернии. Пострадал священномученик Аркадий в начале 1919 года: 10 января он был расстрелян большевиками после жестоких пыток и издевательств." },
  { key: "01-10", name: "сщмч. Александра Дагаева, пресвитера", kind: "saint", desc: "Протоиерей Александр Дагаев родился в 1862 году в городе Бийске в семье протоиерея Владимира Дагаева. В дореволюционное время довольно распространённым явлением были династии священников." },
  { key: "01-10", name: "Феоктиста Хоперскова", kind: "saint", desc: "Священномученик Феоктист (Хоперсков Феоктист Арсеньевич) родился в 1874 году в селе Путим Тамбовской губернии. На момент ареста, который произошел 12 декабря 1937 года, отец Феоктист служил в церкви села Боровок Новодеревенского района Рязанской области." },
  { key: "01-10", name: "Леонида Викторова", kind: "saint", desc: "Иерей Леонид Викторов родился в 1891 году в Рязани в семье диакона. Он рано остался сиротой, и его приняли на бесплатное обучение в Рязанскую Духовную семинарию." },
  { key: "01-10", name: "Николая Родимова", kind: "saint", desc: "Протоиерей Николай Родимов родился в 1856 году в Архангельской губернии в семье священника — отца Даниила Родимова. У отца Даниила было 10 детей: шесть мальчиков и четыре девочки, пятеро его сыновей избрали путь священнослужителя." },
  { key: "01-10", name: "Арефы Насонова", kind: "saint", desc: "Священномученик Арефа родился 24 октября 1888 года в селе Должик Житомирского уезда Волынской губернии в семье крестьян Иоакима и Анны Насоновых. После окончания министерского училища и сдачи экзаменов, необходимых, чтобы занять должность сельского учителя, Арефа Акимович с 1913 года стал преподавать в селе Должик." },
  { key: "01-10", name: "Александра Цицеронова", kind: "saint", desc: "Священник Александр Цицеронов родился 15 августа 1893 года в селе Попадьино Михайловского уезда Рязанской губернии в семье диакона Александра Андреевича Цицеронова и его жены Александры Петровны." },
  { key: "01-11", name: "Попразднство Рождества Христова", kind: "feast", desc: "О событиях праздника Рождества Христова повествуют два евангелиста-синоптика: апостолы Матфей и Лука, причем их рассказы отличаются друг от друга. Конечно, в этом отличии видится особенная ценность каждого повествования, ибо евангелисты взаимно дополняют друг друга и каждый сообщает сведения, не упоминаемые другим." },
  { key: "01-11", name: "Мучеников 14 000 младенцев, от Ирода в Вифлееме убиенных", kind: "saint", desc: "Святые мученики 14 000 младенцев убиты царем Иродом в Вифлееме. Когда пришло время совершения величайшего события – Воплощения Сына Божия и Рождения Его от Пресвятой Девы Марии, восточные волхвы увидели на небе новую звезду, предвозвещавшую рождение Царя Иудейского." },
  { key: "01-11", name: "Прп. Маркелла Апамейского, игумена обители «Неусыпающих»", kind: "saint", desc: "Преподобный Маркелл, игумен обители &quot;Неусыпающих&quot;, был родом из г. Апамеи в Сирии. Он рано лишился своих родителей-христиан. Образование получил сначала в Антиохии, затем в Ефесе." },
  { key: "01-11", name: "прп. Василиска Сибирского", kind: "saint", desc: "Преподобный Василиск Сибирский – святой старец, родился ок. 1740 г. Скончался он в городе Туринске 29 декабря 1824 года и был похоронен в Свято-Николаевском Туринском монастыре." },
  { key: "01-11", name: "прп. Феофила Омучского", kind: "saint", desc: "Неизвестные по происхождению преподобные Феофил и Иаков некоторое время подвизались на острове Коневце, вместе с преподобным Арсением Коневским (память 12/25 июня), и, может быть, там они начали свои иноческие труды." },
  { key: "01-11", name: "прп. Лаврентия Черниговского (Проскуры)", kind: "saint", desc: "Схиархимандрит Лаврентий (в миру Лука Евсеевич Проскура) родился в 1868 году в селе Карыльское Кролевецкого уезда Черниговской губернии. Отец и мать были глубоко религиозные люди и детей воспитывали в вере в Бога." },
  { key: "01-11", name: "прп. Фаддея Студита исп.", kind: "saint", desc: "Преподобный Фаддей Исповедник, ученик Феодора Студита , защитник иконопочитания, пострадал в царствование Льва V (813–820). Во времена господства иконоборцев он был приведен на суд." },
  { key: "01-11", name: "Павла Аношкина, пресвитера", kind: "saint", desc: "Священномученик Павел родился 5 февраля 1891 года в семье мещанина Павла Аношкина. По окончании в 1912 году Пермской Духовной семинарии 19 августа того же года он был рукоположен во священника к Покровской церкви в селе Верх-Сарсы Красноуфи" },
  { key: "01-11", name: "Григория Смирнова, диакона", kind: "saint", desc: "Священномученик Григорий родился 18 ноября 1891 года в Вятской губернии в семье крестьянина Прокопия Смирнова. В 1911 году Григорий окончил второклассное училище при Казанском храме в селе Старый Торъял в Уржумском уезде Вятской губернии, а" },
  { key: "01-11", name: "сщмч. Феодосия Беленького, пресвитера", kind: "saint", desc: "Иерей Феодосий Беленький родился 23 марта 1885 года в селе Успенское Афанасьевского района Днепропетровской области в семье священника. Феодосий окончил Духовную семинарию, в 1917 году принял священный сан и до 1933 года служил на Украине." },
  { key: "01-12", name: "Попразднство Рождества Христова", kind: "feast", desc: "О событиях праздника Рождества Христова повествуют два евангелиста-синоптика: апостолы Матфей и Лука, причем их рассказы отличаются друг от друга. Конечно, в этом отличии видится особенная ценность каждого повествования, ибо евангелисты взаимно дополняют друг друга и каждый сообщает сведения, не упоминаемые другим." },
  { key: "01-12", name: "Мц. Анисии Солунской", kind: "saint", desc: "Святая мученица Анисия жила в городе Солуни (Фессалоники) в царствование императора Максимиана (284–305). По смерти родителей, воспитавших ее в духе христианского благочестия, святая Анисия раздала имущество нищим и стала проводить строгую жизнь в бдении, посте и молитве." },
  { key: "01-12", name: "сщмч. Зотика Сиропитателя, пресвитера", kind: "saint", desc: "Священномученик Зотик, сиропитатель (Ὁ Ἅ&gamma;&iota;&omicron;&sigmaf; &Zeta;&omega;&tau;&iota;&kappa;ὸ&sigmaf; ὁ Ὀ&rho;&phi;&alpha;&nu;&omicron;&tau;&rho;ό&phi;&omicron;&sigmaf;), знатный и богатый римлянин, находился на службе у святого Константина Великого (306–337)." },
  { key: "01-12", name: "свт. Макария, митрополита Московского", kind: "saint", desc: "Свт. Макарий (ок. 1482–1563) – выдающийся церковный и государственный деятель XVI века. Приняв постриг, он прошёл путь от архимандрита до митрополита Московского и всея Руси." },
  { key: "01-12", name: "Ап. от 70-ти Тимона, епископа Бострийского", kind: "saint", desc: "Святые апостолы от 70 Прохор, Никанор, Тимон и Пармен были первыми диаконами Церкви Христовой. В книге Деяний апостолов ( Деян.6:1-6 ) рассказывается, что в Иерусалиме двенадцать апостолов избрали семь мужей: Стефана , Филиппа , Прохора , Н" },
  { key: "01-12", name: "мч. Филетера Никомидийского", kind: "saint", desc: "Святой мученик Филетер Никомидийский дважды претерпел мучения за Христа: при Диоклитиане (284–305) и при Максимиане (305–311). Когда Диоклитиан прибыл в Никомидию, на суд привели святого Филетера, который был высокого роста, с красивым лицом." },
  { key: "01-12", name: "прп. Феодоры Кесарийской", kind: "saint", desc: "Преподобная Феодора Кесарийская, жившая в VIII в., была дочерью патриция Феофила и жены его Феодоры. Родители ее долго не имели детей, о чем скорбели. Они много молились и дали обет, если у них будет дитя, посвятить его Богу." },
  { key: "01-12", name: "прп. Феодоры Константинопольской", kind: "saint", desc: "Преподобная Феодора Цареградская жила в Константинополе в первой половине Х в. Она была замужем, но вскоре овдовела и вела благочестивую жизнь, служа бедным и странникам, а затем приняла монашество и жила под руководством преподобного Василия Нового (память 8 апреля), обитавшего в ее доме в уединенной келлии." },
  { key: "01-12", name: "Мц. Марии Даниловой", kind: "saint", desc: "Данилова Мария Федоровна родилась 25 февраля 1884 года в семье рабочего-ткача. Два года Мария училась в школе, потом пошла по стопам отца: работала мотальщицей и ткачихой." },
  { key: "01-13", name: "Отдание праздника Рождества Христова", kind: "feast", desc: "О событиях праздника Рождества Христова повествуют два евангелиста-синоптика: апостолы Матфей и Лука, причем их рассказы отличаются друг от друга. Конечно, в этом отличии видится особенная ценность каждого повествования, ибо евангелисты взаимно дополняют друг друга и каждый сообщает сведения, не упоминаемые другим." },
  { key: "01-13", name: "Прп. Мелании Римляныни", kind: "saint", desc: "Преподобная Мелания, первая из знатных римлянок &quot;с юных лет стремившаяся ко Христу, жаждущая телесной непорочности и уязвленная Божественной любовью&quot;, родилась в христианской семье." },
  { key: "01-13", name: "прп. Паисия Святогорца", kind: "saint", desc: "Прп. Паисий Святогорец (1924-1994) ‒ один из самых почитаемых греческих святых XX века. Родился в Каппадокии, грудным ребенком привезен в Грецию. В 1954 г.", lifeId: "pausiy-svyatogorets" },
  { key: "01-13", name: "Свт. Петра (Могилы), митрополита Киевского", kind: "saint", desc: "Будущий святитель Петр (Могила) родился 21 декабря 1596 года в Сучаве, третьим сыном в благочестивом семействе высокородных молдавских бояр Могила (в современной румынской транскрипции – Мовилэ), которые в то время занимали господарские престолы Дунайских княжеств." },
  { key: "01-13", name: "свт. Досифея исп., митрополита Загребского (1945)", kind: "saint", desc: "Митрополит Досифей (Васич) родился 5 декабря 1877 года в Белграде. После окончания Белградской духовной семинарии поступил в Киевскую духовную академию, в 1904 году окончил ее со степенью магистра богословия." },
  { key: "01-13", name: "Сщмч. Михаила Березина, пресвитера", kind: "saint", desc: "Михаил Александрович Березин родился 13 июня 1889 года в селе Малое Карачкино Козьмодемьянского уезда Казанской губернии в семье диакона Александра Ивановича Березина." },
  { key: "01-13", name: "мч. Петра Троицкого", kind: "saint", desc: "Мученик Петр родился 29 января 1889 года в селе Макшеево Коломенского уезда Московской губернии в семье диакона Василия Троицкого. Петр окончил духовное училище и поступил в Духовную семинарию, в которой ему пришлось проучиться всего один г" },
  { key: "01-14", name: "По плоти обрезание Господа Бога и Спасителя нашего Иисуса Христа", kind: "feast", desc: "Обрезание в качестве обряда посвящения Божеству существовало у многих народов, в том числе и у египтян. В еврейском понимании кровь священна, так как «кровь есть душа», кровь, текущая из органа, дающего жизнь, означает посвящение Богу жизни, принятой как дар." },
  { key: "01-14", name: "Свт. Василия Великого, архиепископа Кесарии Каппадокийской", kind: "saint", desc: "Василий Великий родился около 330 г. в Кесарии Каппадокийской . В семье свт. Василия к лику святых причислены мать Эмилия (память 14 января), сестра Макрина (память 1 августа), брат Григорий (память 23 января).", lifeId: "vasily-veliky" },
  { key: "01-14", name: "Свт. Афанасия Полтавского, чудотворца", kind: "saint", desc: "Святитель Афанасий был назначен епископом Могилевским и Полоцким в 1795 году. Его политика, выражавшаяся в излишнем администрировании и незнании местных православных общин, привела к росту недовольства." },
  { key: "01-14", name: "мч. Василия Анкирского", kind: "saint", desc: "Святой мученик Василий принадлежал к числу знатных граждан города Анкиры Галатийской (ныне - Анкара, Турция). Пострадал при императоре Юлиане Отступнике." },
  { key: "01-14", name: "св. Емилии, матери свт. Василия Великого", kind: "saint", desc: "Емилия Кесарийская (Каппадокийская) родилась в Кесарии между 305 и 315 годами в богатой семье, которой принадлежали обширные владения в Малой Азии. В юности Емилия отличалась редкой красотой, но, будучи глубоко верующей, готовила себя к безбрачию." },
  { key: "01-14", name: "Прмч. Иеремии (Леонова), монаха", kind: "saint", desc: "Преподобномученик Иеремия (в миру Иван Михайлович Леонов) родился 1 января 1876 года в селе Гаврилопольском Зарайского уезда Курляндской губернии. Он окончил Виленское техническое училище и монастырскую богословскую школу и 12 февраля 1908 года поступил в Валаамский монастырь." },
  { key: "01-14", name: "Платона (Кульбуша), епископа Ревельского, и с ним", kind: "saint", desc: "Священномученик Платон родился 13 июля 1869 года в мызе Подис Перновского уезда Эстляндской губернии в семье псаломщика Петра Кульбуша и его супруги Натальи и наречен был Павлом." },
  { key: "01-14", name: "Михаила Блейве", kind: "saint", desc: "Священномученик Михаил родился 29 октября 1873 года в селе Оллустфере Феллинского уезда Лифляндской губернии в семье псаломщика Иоанна Блейве. Первоначальное образование Михаил получил в Рижском духовном училище." },
  { key: "01-14", name: "Николая Бежаницкого", kind: "saint", desc: "Священномученик Николай родился 14 декабря 1859 года в Лифляндской губернии в семье священника Стефана Бежаницкого. Николай Степанович окончил Рижскую Духовную семинарию и женился на дочери священника Ярославской епархии Иоанна Казаринова Марии." },
  { key: "01-15", name: "Предпразднство Богоявления", kind: "feast", desc: "Установление празднования Рождества Христова относится к первым векам христианства. До IV века в Восточных и Западных Церквах праздник Рождества Христова праздновался 6 января, был известен под именем Богоявления и вначале относился собственно ко Крещению Спасителя." },
  { key: "01-15", name: "Свт. Сильвестра I, папы Римского", kind: "saint", desc: "Святой папа Римский Сильвестр (314–335) родился в Риме от родителей-христиан Руфина и Пусты. Вскоре отец его скончался, и святой остался на попечении матери." },
  { key: "01-15", name: "прав. Иулиании Лазаревской, Муромской", kind: "saint", desc: "Праведная Иулиания Лазаревская (XVI в.) с юности вела благочестивую жизнь, помогая бедным и ухаживая за больными. Вышла замуж за Юрия Осорьина, родила шестерых детей." },
  { key: "01-15", name: "Преставление (1833), второе обретение мощей (1991) прп. Серафима Саровского, чудотворца", kind: "saint", desc: "Прп. Серафим Саровский (в миру Прохор Мошнин, 1754-1833) — великий русский святой, родился в Курске в купеческой семье. В 7 лет упал с колокольни строящегося собора, но остался невредим.", lifeId: "serafim" },
  { key: "01-15", name: "Прп. Сильвестра Печерского, в Ближних пещерах", kind: "saint", desc: "Преподобный Сильвестр Печерский жил в XII веке и был игуменом Михайловского Выдубицкого монастыря в Киеве. Он продолжил труд летописца преподобного Нестора и написал девять житий святых угодников Печерских." },
  { key: "01-15", name: "сщмч. Феогена, епископа Парийского", kind: "saint", desc: "Священномученик Феоген был епископом малоазийского города Пария в начале IV века. В царствование императора Ликиния (307–324), соправителя Константина Великого, трибун Заликинтий принуждал его оставить священный сан, отречься от Христа и поступить на военную службу." },
  { key: "01-15", name: "Мч. Василия Петрова", kind: "saint", desc: "О мученике мирянине Василии Петрове нам известно очень мало. Он родился в 1882 году и принял мученическую кончину от рук богопротивной власти 15 января 1942 года в возрасте шестидесяти лет." },
  { key: "01-16", name: "Предпразднство Богоявления", kind: "feast", desc: "Установление празднования Рождества Христова относится к первым векам христианства. До IV века в Восточных и Западных Церквах праздник Рождества Христова праздновался 6 января, был известен под именем Богоявления и вначале относился собственно ко Крещению Спасителя." },
  { key: "01-16", name: "Прор. Малахии", kind: "saint", desc: "Святой пророк Малахия жил за 400 лет до Рождества Христова, во времена возвращения иудеев из плена вавилонского. Малахия был последним из ветхозаветных пророков, поэтому святые отцы называют его &quot;печатью пророков&quot;." },
  { key: "01-16", name: "мч. Гордия Каппадокийского", kind: "saint", desc: "Мученик Гордий родился в конце III века в городе Кесарии Каппадокийской в христианской семье. В зрелом возрасте поступил на военную службу и, проявив мужество и воинское искусство, был назначен сотником." },
  { key: "01-16", name: "Прп. Женевьевы (Геновефы) Парижской", kind: "saint", desc: "Родиной святой Геновефы [*] ((фр. Genevi&egrave;ve), или Геновефа (лат. Genovefa)) является Галлия, или теперешняя Франция. Завоеванная в 52-м году до Рождества Христова Юлием Цезарем, она стала одной из римских провинций, а коренное населе" },
  { key: "01-16", name: "Сщмч. Василия Холмогорова, пресвитера", kind: "saint", desc: "Священномученик Василий родился 25 января 1875 года в селе Андреевском Коломенского уезда Московской губернии в семье священника Ивана Васильевича Холмогорова." },
  { key: "01-17", name: "Предпразднство Богоявления", kind: "feast", desc: "Установление празднования Рождества Христова относится к первым векам христианства. До IV века в Восточных и Западных Церквах праздник Рождества Христова праздновался 6 января, был известен под именем Богоявления и вначале относился собственно ко Крещению Спасителя." },
  { key: "01-17", name: "Собор 70-ти апостолов", kind: "feast", desc: "Собор святых семидесяти апостолов был установлен Православной Церковью для того, чтобы показать равночестие каждого из семидесяти и тем самым предотвратить разногласия в почитании их." },
  { key: "01-17", name: "Прп. Феоктиста, игумена Кукума Сикелийского", kind: "saint", desc: "Преподобный Феоктист основал обитель в городе Кукуме на острове Сицилия, где стал игуменом. В его монастыре жили греческие монахи, бежавшие от преследований иконоборцев." },
  { key: "01-17", name: "свт. Евстафия I, архиепископа Сербского", kind: "saint", desc: "Свт. Евстафий, архиепископ Сербский (XIII век), родился в благочестивой семье, принял монашество в монастыре Архангела Михаила в Черногории. Совершил паломничество в Иерусалим и на Афон, где стал игуменом Хиландарского монастыря." },
  { key: "01-17", name: "Прп. Ахилы, диакона Печерского, в Дальних пещерах", kind: "saint", desc: "Преподобный отец наш Ахила диакон (XIV в.), возлюбив от младенчества постническую жизнь и отвергши мир, пришел в Печерский монастырь, чтобы здесь угодить Господу." },
  { key: "01-17", name: "прмч. Зосимы пустынника", kind: "saint", desc: "Прмч. Зосима, живший в IV веке, был христианином, удалившимся от мира в пустыню. Однажды его обнаружил правитель Киликии Дометиан, увидев, как старец мирно беседует с дикими зверями." },
  { key: "01-17", name: "мч. Афанасия", kind: "saint", desc: "Святой Зосима был родом с Сицилии, вел аскетическую жизнь в пустыне, соседствуя с дикими зверями. Арестованный по приказу правителя Домициана, он исповедал Христа воистину воплощенным Богом." },
  { key: "01-17", name: "сщмч. Николая Маслова, пресвитера", kind: "saint", desc: "Священномученик Николай (Николай Иванович Маслов) родился в 1874 году в городе Твери. По окончании духовного училища и пастырских курсов, в 1924 году он был рукоположен во священника и служил в Твери в храме в честь иконы Божией Матери «Неопалимая Купина» за Волгой." },
  { key: "01-17", name: "сщмч. Павла Фелицына, пресвитера", kind: "saint", desc: "Священномученик Павел родился в 1894 году в селе Карпово Дмитровского уезда Московской губернии в семье священника Иоанна Фелицына. В 1910 году Павел окончил Дмитровское духовное училище, а в 1914 году училище имени Шелапутина в Москве и поступил псаломщиком в Воскресенскую церковь в селе Карпово." },
  { key: "01-18", name: "Навечерие Богоявления", year: "Крещенский сочельник", kind: "feast", desc: "18 января (5 января по старому стилю) — в Русской Православной Церкви день Навечерия Крещения Господня или Крещенский сочельник. Слово навечерие означает преддверие церковного торжества, а второе название — сочельник (или сочевник) связано " },
  { key: "01-18", name: "прп. Синклитикии Александрийской", kind: "saint", desc: "Преподобная Синклитикия родом из Александрии, дочь богатых родителей, прекрасная собой, с юных лет помышляла только об угождении Богу. Возлюбив чистоту девства, она отказалась вступить в брак и всё время проводила в посте и молитве." },
  { key: "01-18", name: "прп. Симеона Псково-Печерского", kind: "saint", desc: "Преподобный Симеон (в миру Василий Иванович Желнин) родился 1 марта 1869 года в деревне Яковлевской Островского уезда Псковской губернии в крестьянской семье от родителей Иоанна и Наталии." },
  { key: "01-18", name: "Прор. Михея", kind: "saint", desc: "Сын Иемвлая. Жил в IX веке до Р. Х и происходил из колена Ефремова, был современником пророка Илии. Святой пророк Михей обличал израильского царя Ахава за отпадение от Бога в идолопоклонство и предсказал ему гибель в войне с ассирийцами, за что был посажен в темницу, где кормили его только хлебом и водой." },
  { key: "01-18", name: "прп. Аполлинарии", kind: "saint", desc: "Преподобная Аполлинария была дочерью Анфемия, бывшего правителя Греческой империи во время малолетства Феодосия Младшего (408–450). Отказавшись от брака, она выпросила у своих благочестивых родителей разрешение поклониться святым местам Востока." },
  { key: "01-18", name: "прп. Фостирия", kind: "saint", desc: "Преподобный Фостирий, пустынник, подвизался на высокой горе. Силой чудотворений и святостью жизни многих отвратил от ересей. Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите " },
  { key: "01-18", name: "прп. Мины Синайского", kind: "saint", desc: "Преподобный Мина 50 лет подвизался в Синайском монастыре, скончался мирно во второй половине VI века. Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите кнопку " },
  { key: "01-18", name: "прп. Григория Акритского", kind: "saint", desc: "Преподобный Григорий Акритский родился на острове Крит в 760 году. Он получил образование от благочестивых родителей. То было время, когда еретики-иконоборцы притесняли православных." },
  { key: "01-18", name: "Сщмч. Андрея Зимина, протоиерея", kind: "saint", desc: "Протоиерей Андрей Симеонович Зимин [1] родился 14 августа 1872 года в семье забайкальского казака. После окончания полного курса Благовещенской духовной семинарии был рукоположен в сентябре 1894 года в диакона и священника для служения в ка" },
  { key: "01-18", name: "мч. Иосифа Беспалова и с ним 37-ми мучеников", kind: "saint", desc: "Мученик Иосиф (Иосиф Яковлевич Беспалов) был старостой в Никольской церкви в станице Талгар Верненского уезда Семиреченской области. 18 января 1921 года он был расстрелян большевиками в станице Талгар вместе с тридцатью семью православными прихожанами." },
  { key: "01-18", name: "мц. Евгении Доможировой", kind: "saint", desc: "Мученица Евгения родилась в 1871 году в городе Риге в семье генерала Петра Доможирова. Пять лет она училась в институте благородных девиц в Варшаве и одновременно в школе Красного Креста." },
  { key: "01-18", name: "сщмч. Сергия Лаврова, пресвитера", kind: "saint", desc: "Священномученик Сергий родился в 1872 году в селе Кулики Моршанского уезда Тамбовской губернии в семье священника Николая Лаврова. По окончании в 1893 году Тамбовской Духовной семинарии Сергей Николаевич был назначен учителем в школу в деревне Васильевщина Моршанского уезда." },
  { key: "01-18", name: "мч. Матфея Гусева", kind: "saint", desc: "Мученик Матфей родился 9 августа 1868 года в селе Нахабино Павловской волости Звенигородского уезда Московской губернии в семье крестьянина Ивана Гусева." },
  { key: "01-19", name: "Святое Богоявление. Крещение Господа Бога и Спаса нашего Иисуса Христа", kind: "great", desc: "Установление празднования Рождества Христова относится к первым векам христианства. До IV века в Восточных и Западных Церквах праздник Рождества Христова праздновался 6 января, был известен под именем Богоявления и вначале относился собственно ко Крещению Спасителя." },
  { key: "01-19", name: "Преставление свт. Феофана, Затворника Вышенского", kind: "saint", desc: "Свт. Феофан Затворник (1815–1894) – выдающийся русский богослов, проповедник и духовный писатель. Окончив Киевскую Духовную Академию, принял монашество (1841), преподавал в СПДА, затем был направлен в Иерусалим, где изучал святые места и труды отцов Церкви.", lifeId: "feofan-zatvornik" },
  { key: "01-20", name: "Попразднство Богоявления", kind: "feast", desc: "Установление празднования Рождества Христова относится к первым векам христианства. До IV века в Восточных и Западных Церквах праздник Рождества Христова праздновался 6 января, был известен под именем Богоявления и вначале относился собственно ко Крещению Спасителя." },
  { key: "01-20", name: "Собор Пророка, Предтечи и Крестителя Господня Иоанна", kind: "feast", desc: "Пророк Иоанн Креститель – после Девы Марии самый чтимый святой. С именем Иоанна Предтечи связано семь праздников (по новому стилю): Пророк Иоанн Креститель был сыном священника Захарии (из рода Аарона) и праведной Елизаветы (из рода царя Давида).", lifeId: "ioann-predtecha" },
  { key: "01-21", name: "Попразднство Богоявления", kind: "feast", desc: "Установление празднования Рождества Христова относится к первым векам христианства. До IV века в Восточных и Западных Церквах праздник Рождества Христова праздновался 6 января, был известен под именем Богоявления и вначале относился собственно ко Крещению Спасителя." },
  { key: "01-21", name: "Прп. Георгия Хозевита", kind: "saint", desc: "Преподобный Георгий Хозевит родился на острове Кипре. По смерти родителей он отправился в Палестину на поклонение святым местам. Здесь он поступил в иноческую Хузивитскую общину, находившуюся между рекой Иорданом и Иерусалимом, настоятелем которой он стал впоследствии.", lifeId: "georgiy" },
  { key: "01-21", name: "прп. Домники Константинопольской, игумении", kind: "saint", desc: "Преподобная Домника прибыла из Карфагена в Царьград при святом царе Феодосии Великом. Здесь она приняла Крещение от патриарха Нектария и поступила в монастырь." },
  { key: "01-21", name: "прп. Емилиана исп., епископа Кизического", kind: "saint", desc: "Исповедник Емилиан, епископ Кизический (IX в.). В 815 году при императоре-иконоборце Льве Армянине мужественно отказался отвергнуть почитание икон. Был сослан в заточение, где и скончался." },
  { key: "01-21", name: "прп. Григория, чудотворца Печерского, в Ближних пещерах", kind: "saint", desc: "Преподобный Григорий был пострижен в иночество в Киево-Печерском монастыре при преподобном Феодосии (&dagger; 1074; память 3 мая). Много времени святой уделял чтению книг, которые были единственным его достоянием." },
  { key: "01-21", name: "прп. Григория, затворника Печерского, в Дальних пещерах", kind: "saint", desc: "Преподобный Григорий, затворник Киево-Печерский, жил в XIV веке. В &quot;Сказании о житиях святых, в пещере преподобного Феодосия почивающих&quot; говорится, что пищей преподобного Григория всю жизнь служила невареная трава." },
  { key: "01-21", name: "сщмч. Исидора Юрьевского (Дерптского), пресвитера, и с ним 72-х, в Юрьеве Лифляндском пострадавших", kind: "saint", desc: "В 1472 году в г. Юрьеве (Тарту) в праздник Богоявления священник церкви святителя Николая о. Исидор во время великого освящения воды на реке Омовже был схвачен по приказу ливонского бискупа и заключен в темницу." },
  { key: "01-21", name: "Прп. Паисия Угличского, игумена", kind: "saint", desc: "Прп. Паисий Угличский (XV–XVI вв.) ‒ племянник и ученик прп. Макария Калязинского. С 11 лет воспитывался в монастыре, где подвизался в посте, молитве и переписывании книг." },
  { key: "01-21", name: "сщмч. Картерия, пресвитера Кесарии Каппадокийской", kind: "saint", desc: "Иерей и учитель христианский в Кесарии Каппадокийской, при императоре Диоклитиане и игемоне Урбане, за исповедание веры и проповеди о Иисусе Христе после тяжких мук умер от копья жидовина в 304 году." },
  { key: "01-21", name: "прп. Илии Египетского", kind: "saint", desc: "С юных лет был монахом и после 70-летних подвигов на некоей горе, в дикой пустыне нижней Фиваиды, близ Антиноя, скончался 110 лет в конце 4 века. Изображается в виде седого старца, лицо морщиноватое и бледное, волосы простые, в одной рясе." },
  { key: "01-21", name: "мч. Або Тбилисского (786)", kind: "saint", desc: "Мученик Або Тбилели (Тбилисский), араб по происхождению, жил в VIII в. в Багдаде и был изготовителем благовонных мазей. В возрасте 17–18 лет он оказался в Тбилиси, последовав за правителем Картли (Восточная Грузия) – Нерсесом." },
  { key: "01-21", name: "Сщмч. Виктора Усова, пресвитера", kind: "saint", desc: "Священномученик Виктор родился 19 марта 1876 года в селе Всехсвятско-Орловский Погост Великоустюжского уезда Вологодской губернии в семье диакона Симеона Васильевича Усова и жены его Агнии." },
  { key: "01-21", name: "сщмчч. Димитрия Плышевского", kind: "saint", desc: "Священномученик Димитрий родился в 1880 году в семье священнослужителя Иоанна Плышевского. По окончании в 1905 году Минской Духовной семинарии он был рукоположен во священника и служил в Николаевской церкви в селе Смолевичи Минского уезда." },
  { key: "01-21", name: "Владимира Пастернацкого", kind: "saint", desc: "Священномученик Владимир родился 2 июля 1885 года в селе Дудичи Игуменского уезда Минской губернии в семье священника Илариона Пастернацкого, настоятеля Покровской церкви в селе Дудичи." },
  { key: "01-22", name: "Попразднство Богоявления", kind: "feast", desc: "Установление празднования Рождества Христова относится к первым векам христианства. До IV века в Восточных и Западных Церквах праздник Рождества Христова праздновался 6 января, был известен под именем Богоявления и вначале относился собственно ко Крещению Спасителя." },
  { key: "01-22", name: "Мч. Полиевкта Мелитинского", kind: "saint", desc: "Святой Полиевкт был первым мучеником в армянском городе Мелитине. Он был воином при императоре Декии (249–251) и пострадал за веру во Христа при императоре Валериане (253–259)." },
  { key: "01-22", name: "Прп. Ионы (в схиме Петра) Киевского, чудотворца", kind: "saint", desc: "Преподобный Иона Киевский родился в 1802 году в бедной семье. Был набожным с детства, часто посещал монастыри и первоначально поселился у старца Серафима Саровского." },
  { key: "01-22", name: "прор. Самея", kind: "saint", desc: "Пророк Самей жил при царе Соломоне и сыне его Ровоаме, которому пророк от лица Божия запретил воевать против 10 колен Израилевых, отделившихся от потомков Давидовых ( 3Цар.12 )." },
  { key: "01-22", name: "свт. Петра, епископа Севастии Армянской", kind: "saint", desc: "Святитель Петр, епископ Севастийский, был братом святителей Василия Великого и Григория Нисского (память 1 и 10 января). В воспитании его принимала большое участие старшая сестра, благочестивая Макрина (память 19 июля)." },
  { key: "01-22", name: "прп. Евстратия Тарсийского, чудотворца, игумена", kind: "saint", desc: "Преподобный Евстратий происходил из города Тарса. 20-ти лет он тайно ушел из дома родителей и поселился в Авгаровской обители (на Олимпе в Малой Азии)." },
  { key: "01-22", name: "Сщмч. Павла Никольского, пресвитера", kind: "saint", desc: "Священномученик Павел родился 8 сентября 1896 года в городе Зарайске Рязанской губернии в семье псаломщика Дмитрия Павловича Никольского и его супруги Анастасии." },
  { key: "01-23", name: "Попразднство Богоявления", kind: "feast", desc: "Установление празднования Рождества Христова относится к первым векам христианства. До IV века в Восточных и Западных Церквах праздник Рождества Христова праздновался 6 января, был известен под именем Богоявления и вначале относился собственно ко Крещению Спасителя." },
  { key: "01-23", name: "Свт. Григория, епископа Нисского", kind: "saint", desc: "Святитель Григорий, епископ Нисский, был младшим братом святителя Василия Великого (память 1 января). Рождение и воспитание его совпало с самым разгаром арианских споров." },
  { key: "01-23", name: "прп. Дометиана, епископа Мелитинского", kind: "saint", desc: "Преподобный Дометиан, епископ Мелитинский, родился и жил в VI веке, при императоре Иустине Младшем. Был женат, но вскоре овдовел, принял монашество и проводил строгую и святую жизнь." },
  { key: "01-23", name: "свт. Феофана, Затворника Вышенского", kind: "saint", desc: "Свт. Феофан Затворник (1815–1894) – выдающийся русский богослов, проповедник и духовный писатель. Окончив Киевскую Духовную Академию, принял монашество (1841), преподавал в СПДА, затем был направлен в Иерусалим, где изучал святые места и труды отцов Церкви.", lifeId: "feofan-zatvornik" },
  { key: "01-23", name: "прп. Маркиана Константинопольского, пресвитера", kind: "saint", desc: "Преподобный Маркиан, пресвитер и эконом Великой церкви (в Константинополе), родился в Риме и в юности получил начальное образование в Константинополе. После смерти родителей преподобный Маркиан употребил богатое наследство на строение, обновление и украшение храмов." },
  { key: "01-23", name: "прп. Павла Комельского (Обнорского)", kind: "saint", desc: "Преподобный Павел Комельский, славный ученик преподобного Сергия Радонежского, родился в Москве в 1317 году. С юных лет он отличался благочестием и милосердием к бедным и страждущим." },
  { key: "01-23", name: "прп. Антипы Валаамского (Афонского)", kind: "saint", desc: "Иеросхимонах Антипа родился в Молдавии, в селе Калаподешти Текунчского уезда в 1816 году. Родители его были люди православные и весьма благочестивые. Жили они в большой бедности." },
  { key: "01-23", name: "Прп. Макария Писемского", kind: "saint", desc: "Подвизался в XIV веке и был сподвижником преподобного Павла Обнорского (&dagger; 1429 г.). Иноческие подвиги святой начал в обители преподобного Сергия Радонежского, но по любви к уединению удалился в густой лес близ речки Письмы, где впоследствии основал монастырь и после своей кончины был там погребен." },
  { key: "01-23", name: "блж. Феосевии (Феозвы), диаконисы, сестры свт. Григория Нисского", kind: "saint", desc: "Блаженная Феозва диакониса была родной сестрой святых Василия Великого , Григория Нисского и Петра, епископа Севастийского. Она была девственницей и служила Святой Церкви диакониссой, ухаживала за больными, раздавала пищу странникам, воспитывала сирот и готовила женщин ко Святому Крещению." },
  { key: "01-23", name: "Сщмч. Зиновия Сутормина, пресвитера", kind: "saint", desc: "Священномученик Зиновий (Зиновий Евстафьевич Сутормин) до принятия священнического сана служил фельдшером в Сибирском казачьем войске. В 1901 году он был рукоположен во диакона к Воскресенскому храму в городе Семипалатинске, а в 1911 году —" },
  { key: "01-23", name: "сщмч. Петра Успенского, пресвитера", kind: "saint", desc: "Священномученик Петр родился в 1863 году в селе Меньшие Можары Сапожковского уезда Рязанской губернии в семье священника Николая Успенского. В 1884 году Петр Николаевич окончил Рязанскую Духовную семинарию и в течение десяти лет работал учителем в школах сел Юраково и Панкино Пронского уезда Рязанской губернии." },
  { key: "01-23", name: "сщмч. Анатолия (Грисюка), митрополита Одесского", kind: "saint", desc: "Священномученик Анатолий родился 19 августа 1880 года в городе Кременце Волынской губернии в семье бухгалтера Кременецкого уездного казначейства Григория Грисюка и в крещении наречен был Андреем." },
  { key: "01-24", name: "Попразднство Богоявления", kind: "feast", desc: "Установление празднования Рождества Христова относится к первым векам христианства. До IV века в Восточных и Западных Церквах праздник Рождества Христова праздновался 6 января, был известен под именем Богоявления и вначале относился собственно ко Крещению Спасителя." },
  { key: "01-24", name: "Прп. Феодосия Великого, общих житий начальника", kind: "saint", desc: "Родом из Каппадокии. Воспитан родителями в глубоком благочестии. Стремясь к отшельнической жизни, поселился в Палестине в пустынной пещере, в которой, по преданию, ночевали три волхва, пришедшие поклониться родившемуся Спасителю мира." },
  { key: "01-24", name: "прп. Михаила Клопского, Новгородского", kind: "saint", desc: "Преподобный Михаил Клопский происходил из боярского рода, был родственником великого князя Димитрия Донского (1363-1389). Он принял на себя подвиг юродства Христа ради, покинул Москву и в рубище пришел в Клопский монастырь, близ Новгорода." },
  { key: "01-24", name: "Прп. Феодосия Антиохийского", kind: "saint", desc: "Преподобный Феодосий Антиохийский с юных лет оставил богатый дом своих знатных родителей и вступил на тесный и скорбный путь подвижничества, поселившись в малой келлии на берегу Исского залива, в окрестностях города Росс." },
  { key: "01-24", name: "Прп. Пахомия Кенского, игумена (XVI)", kind: "saint", desc: "Был учеником и сомолитвенником преподобного Александра Ошевенского. Пахомий вышел из обители наставника вскоре после его смерти. Строгий постник и молитвенник, Пахомий много лет провел в уединении." },
  { key: "01-24", name: "Владимира Фокина, пресвитеров", kind: "saint", desc: "Священномученик Владимир Фокин в 1895 году служил псаломщиком в Белоярской Ильинской церкви, в 1908-м — диаконом в селе Солгонское, в 1915 году — священником в селе Ново-Еловское Ачинского уезда Красноярского края [1] ." },
  { key: "01-24", name: "св. Владимира Хираско, исп., пресвитера", kind: "saint", desc: "Священноисповедник Владимир родился 11 января 1874 года в городе Петровске [1] Киевской губернии в семье священнослужителя Григория Хираско. По окончании Духовной семинарии Владимир Григорьевич работал учителем в церковноприходских школах." },
  { key: "01-24", name: "Елецкая", year: "1060", kind: "saint", desc: "Об этой иконе известно лишь то, что находилась она в городе Ельце Орловской губернии. Кроме того, летописи зафиксировали год её явления — 1060, то есть тот же, что и у Елецкой-Черниговской." },
  { key: "01-25", name: "Попразднство Богоявления", kind: "feast", desc: "Установление празднования Рождества Христова относится к первым векам христианства. До IV века в Восточных и Западных Церквах праздник Рождества Христова праздновался 6 января, был известен под именем Богоявления и вначале относился собственно ко Крещению Спасителя." },
  { key: "01-25", name: "Мц. Татианы Римской, диаконисы, и с нею в Риме пострадавших", kind: "saint", desc: "Святая Татиана была дочерью богатого римлянина и была воспитана им в христианской вере. Когда Татиана достигла совершеннолетия, она стала равнодушна к богатству и иным благам и возлюбила всем сердцем духовный образ жизни.", lifeId: "tatiana" },
  { key: "01-25", name: "свт. Саввы I, архиепископа Сербского", kind: "saint", desc: "Свт. Савва Сербский (ок. 1169‒1237) ‒ первый архиепископ автокефальной Сербской Православной Церкви, сын св. правителя Стефана Немани. В 17 лет принял монашество на Афоне, где основал Хиландарский монастырь." },
  { key: "01-25", name: "прп. Мартиниана Белоезерского, игумена", kind: "saint", desc: "Прп. Мартиниан Белозерский (ок. 1397–1483) – ученик прп. Кирилла Белозерского. В 13 лет пришел в его монастырь, где научился грамоте и переписыванию книг." },
  { key: "01-25", name: "Мч. Мертия", kind: "saint", desc: "Мученик Мертий был воином, пострадал за имя Христово при Диоклитиане (284–305) в Африке. Император принуждал его принести жертву идолам и, получив отказ, предал на истязания." },
  { key: "01-25", name: "мч. Петра Авессаломита (Анийского)", kind: "saint", desc: "Мученик Петр Авессаломит (Анийский) был родом из селения Анеи в Палестине. Во время гонения на христиан был схвачен и доставлен к правителю Палестины. Напрасно убеждали его судья и народ почтить языческих богов, чтобы избавиться от мучений." },
  { key: "01-25", name: "прп. Евпраксии Тавенской", kind: "saint", desc: "Преподобная Евпраксия Тавенисская (Тавенская, Старшая), мать преподобной Евпраксии, девы Тавенисской (память 25 июля), была супругой благочестивого сенатора Антигона, который состоял в родстве с императором Феодосием Великим (379–395)." },
  { key: "01-25", name: "Акафистная Хиландарская", kind: "saint", desc: "Икона Божией Матери «Акафистная» находится в иконостасе соборного храма Введения Богородицы сербского Хиландарского монастыря на Афоне. Данных о появлении и истории прославления образа на Святой горе не сохранилось." },
  { key: "01-25", name: "Млекопитательница", kind: "saint", desc: "Икона Божией Матери «Млекопитательница» является одним из лучших образцов византийской школы и имеет богатую историю, связанную с именем святого Саввы Освященного, в Лавре которого близ Иерусалима она первоначально и находилась." },
  { key: "01-26", name: "Попразднство Богоявления", kind: "feast", desc: "Установление празднования Рождества Христова относится к первым векам христианства. До IV века в Восточных и Западных Церквах праздник Рождества Христова праздновался 6 января, был известен под именем Богоявления и вначале относился собственно ко Крещению Спасителя." },
  { key: "01-26", name: "прп. Иринарха, затворника Ростовского", kind: "saint", desc: "Преподобный Иринарх, затворник Ростовский, родился в крестьянской семье в селе Кондаково Ростовского уезда. В Крещении он получил имя Илия. На 30-м году жизни святой принял постриг в монашество в Ростовском Борисоглебском монастыре." },
  { key: "01-26", name: "прп. Елеазара Анзерского (Севрюкова)", kind: "saint", desc: "Преподобный Елеазар Анзерский родился в городе Козельске в семье купцов Севрюковых. По благословению родителей он удалился в Соловецкий монастырь, где принял постриг от игумена преподобного Иринарха (&dagger; 1628; память 17 июля)." },
  { key: "01-26", name: "Мч. Петра Авессаломита (Анийского)", kind: "saint", desc: "Мученик Петр Авессаломит (Анийский) был родом из селения Анеи в Палестине. Во время гонения на христиан был схвачен и доставлен к правителю Палестины. Напрасно убеждали его судья и народ почтить языческих богов, чтобы избавиться от мучений." },
  { key: "01-26", name: "прп. Иакова, епископа Низибийского", kind: "saint", desc: "Преподобный Иаков, епископ Низибийский, был сыном князя Гефальского (Армения) и получил хорошее образование. С юности он полюбил уединение, долгое время жил в горах, около города Низибии (на границе Персии и Римской империи), где нес самые " },
  { key: "01-26", name: "прп. Максима Кавсокаливита", kind: "saint", desc: "Преподобный Максим Кавсокаливит воспитывался при храме Пресвятой Богородицы в Лампсаке. В семнадцатилетнем возрасте он оставил родительский дом, принял монашество и проходил послушание у лучшего духовного наставника Македонии – старца Марка." },
  { key: "01-27", name: "Отдание праздника Богоявления", kind: "feast", desc: "Установление празднования Рождества Христова относится к первым векам христианства. До IV века в Восточных и Западных Церквах праздник Рождества Христова праздновался 6 января, был известен под именем Богоявления и вначале относился собственно ко Крещению Спасителя." },
  { key: "01-27", name: "равноап. Нины, просветительницы Грузии", kind: "saint", desc: "Святая Нина была племянницей Иерусалимского патриарха Ювеналия. Она с юности всем сердцем возлюбила Бога и глубоко сожалела о людях, не верующих в Него." },
  { key: "01-27", name: "Прп. Иосифа Аналитина Раифского", kind: "saint", desc: "Преподобный Иосиф Аналитин, Раифский, строгий подвижник, достиг высокого совершенства в духовной жизни, так что во время молитвы его осеняло пламя. Предсказав время своей кончины ученику своему Геласию, он мирно скончался в IV веке, до избиения отцов Синайских." },
  { key: "01-27", name: "прп. Феодула, иеромонаха", kind: "saint", desc: "Преподобный Феодул был сыном преподобного Нила Постника (память 12 ноября), описавшего убиение святых отцов в Раифе в V веке. Еще в отроческие годы преподобный Феодул удалился вместе со своим отцом на Синайскую гору, оставив мир." },
  { key: "01-27", name: "прп. Стефана Вифинского (Халкидонского)", kind: "saint", desc: "Преподобный Стефан жил в VIII веке. Подражая жизни великих подвижников, он обошел много обителей в Палестине, посетил также пустыни великих отцов – преподобных Евфимия Великого (память 20 января), Саввы Освященного (память 5 декабря) и Феодосия Великого (память 11 января)." },
  { key: "01-27", name: "Антония (Чиркова), иеромонаха", kind: "saint", desc: "Преподобномученик Антоний (Чирков) (1868–1930), в миру Чирков Антон Иванович, родился в 1868 году [1] в г. Чистополе Казанской губернии, в семье мещан." },
  { key: "01-27", name: "Варлаама (Похилюка), иеромонаха", kind: "saint", desc: "Преподобномученик Варлаам (в миру Похилюк Виктор Семенович) родился в 1870 году, в селе Парпуровцы Винницкого уезда Подольской губернии. Из крестьянской семьи, окончил церковноприходскую школу." },
  { key: "01-27", name: "Иосифа", kind: "saint", desc: "Иосиф (Гаврилов) (1888 – 1930), иеромонах, преподобномученик. В миру Гаврилов Иван Илларионович, родился 16 октября 1888 года в благочестивой крестьянской семье." },
  { key: "01-27", name: "Сергия", kind: "saint", desc: "Сергий (Гуськов) (1875 — 1930), иеромонах, преподобномученик (местночтимый святой Казанской епархии). В миру Гуськов Павел Иванович, родился в 1875 году в благочестивой крестьянской семье." },
  { key: "01-27", name: "Петра (Тупицына)", kind: "saint", desc: "Тупицын Петр (1906 — 1930), послушник, преподобномученик (местночтимый святой Казанской епархии). Родился в 1906 году в доброй крестьянской семье. Окончив сельскую школу, и будучи уже в юном возрасте глубоко религиозным, ушел скитаться по святым местам, желая найти тихую обитель для уединенной монашеской жизни." },
  { key: "01-27", name: "прп. Иоанна (Кевролетина), исп., иеросхимонаха", kind: "saint", desc: "Преподобноисповедник Иоанн родился 23 мая 1875 года в деревне Кулаково Троицкого уезда Тобольской губернии в семье крестьянина Афанасия Кевролетина. Образование получил дома." },
  { key: "01-28", name: "Павла Фивейского", kind: "saint", desc: "Преподобный Павел Фивейский родился в Египте, в городе Фиваиде. Оставшись сиротой, он много претерпел от своего корыстолюбивого родственника из-за родительского наследства." },
  { key: "01-28", name: "Иоанна Кущника", kind: "saint", desc: "Преподобный Иоанн Кущник (Каливит) был сыном богатых и знатных родителей, живших в Константинополе в V веке. С юности возлюбив Христа больше всего земного, упросил родителей подарить ему Евангелие, чтобы, читая, делом исполнять написанное." },
  { key: "01-28", name: "Прмч. Пансофия Александрийского", kind: "saint", desc: "Мученик Пансофий был сыном правителя Александрии. После смерти отца он роздал нищим все отцовское имущество и удалился в пустыню. Здесь он подвизался около 30 лет." },
  { key: "01-28", name: "Прохора Пшинского", kind: "saint", desc: "Преподобный Прохор Пшинский (Пчиньский) подвизался в пустыне Вранской на реке Пшине и основал там обитель. Известен как один из самых строгих подвижников иноческого жития и представитель сербского исихазма ." },
  { key: "01-28", name: "Гавриила Лесновского (XI)", kind: "saint", desc: "Преподобный Гавриил, основатель Лесновского монастыря близ города Кратова, получив после смерти родителей большое наследство, отказался от супружества, ушел на Лесновскую гору и стал монахом." },
  { key: "01-28", name: "свт. Герасима II (Палладаса), патриарха Александрийского", kind: "saint", desc: "Святитель Герасим родился в Хандаке на острове Крит. Первым учителем будущего патриарха был его отец – протопресвитер Феодор. После домашнего воспитания и обучения родители отправили его в Венецию для получения высшего образования в венецианской Флангиановой коллегии." },
  { key: "01-28", name: "Сщмч. Михаила Самсонова, пресвитера", kind: "saint", desc: "Согласно документам, в церкви села Раскильдино Шемуршинского района Чувашии во время размаха репрессий священником служил Самсонов Михаил Самсонович. В декабре 1937 года его арестовали и осудили на 10 лет тюремного заключения." },
  { key: "01-29", name: "Поклонение честным веригам ап. Петра", kind: "feast", desc: "Около 42 года апостол Петр по повелению Ирода Агриппы был заключен в темницу за проповедь о Христе Спасителе. В темнице он был связан двумя железными цепями." },
  { key: "01-29", name: "Прав. Максима, иерея Тотемского", kind: "saint", desc: "Жил в первой половине XVII в. В течение 45 лет он проходил добровольный подвиг юродства Христа ради и пребывал в непрестанной молитве, посте, наготе, совершенно пренебрегал заботами о своем теле." },
  { key: "01-29", name: "мч. Данакта Иллирийского, чтеца", kind: "saint", desc: "Святой мученик Данакт жил во II веке и служил чтецом при церкви в местечке Авлон, в Иллирии. Во время нашествия неверных святой взял церковные сосуды и хотел скрыться, но был схвачен воинами." },
  { key: "01-29", name: "свт. Гонората, епископа Арльского", kind: "saint", desc: "Святой Гонорат [*] (429 г.) родился во второй половине IV века в бельгийской Галлии в аристократической семье. Его отец противился стремлению сына к благочестивой жизни." },
  { key: "01-29", name: "Сщмч. Иоанна Петтайя, пресвитера", kind: "saint", desc: "Священномученик Иоанн родился 1 января 1894 года в местечке Каролен Верроского уезда Лифляндской губернии в семье православных крестьян-батраков, работавших в помещичьем имении Каролен, Михаила Яковлевича и Марии Константиновны Петтай." },
  { key: "01-30", name: "Прп. Антония Великого", kind: "saint", desc: "Антоний Великий родился в Египте около 250 года от благородных и богатых родителей, воспитавших его в христианской вере. Восемнадцати лет он лишился своих родителей и остался один с сестрой, которая была на его попечении." },
  { key: "01-30", name: "прп. Антония Дымского", kind: "saint", desc: "Прп. Антоний Дымский (ок. 1157–1224) родился в Новгороде, с юных лет стремился к подвижничеству. Принял постриг в Хутынском монастыре у прп. Варлаама Хутынского, после его смерти стал игуменом обители." },
  { key: "01-30", name: "Прп. Антония Черноезерского", kind: "saint", desc: "Преподобный Антоний Черноезерский основал Богородицкий монастырь на Черном озере в Новгородских владениях, неподалеку от города Череповца. Монастырь был расположен на острове у Щирского погоста." },
  { key: "01-30", name: "Сщмч. Виктора Европейцева, пресвитера", kind: "saint", desc: "Священномученик Виктор родился в 1885 году в селе Малый Азясь Краснослободского уезда Пензенской губернии в семье священника Андрея Европейцева. По окончании Духовной семинарии он был рукоположен во священника и с 1906 года служил в храме святых бессребреников Космы и Дамиана в селе Хлыстовка Краснослободского уезда." },
  { key: "01-30", name: "сщмч. Павла Успенского, пресвитера", kind: "saint", desc: "Священномученик Павел (Павел Никитич Успенский) родился 21 января 1874 года в селе Романово Переславского уезда Владимирской губернии в семье священника Никиты Успенского." },
  { key: "01-31", name: "Афанасия Великого (373) и", kind: "saint", desc: "Святой Афанасий родился в Александрии; мать его, подобно Анне, которая привела сына своего Самуила в храм Господень ( 1Цар.1:28 ), так же привела его к св." },
  { key: "01-31", name: "Кирилла (444), архиепископов Александрийских", kind: "saint", desc: "Свт. Кирилл Александрийский (†444) – выдающийся богослов и защитник Православия. Возглавив Александрийскую Церковь в 412 г., он боролся с ересями новациан и иудеев, а позже – с несторианством, отрицавшим Божественное достоинство Христа и наименование Девы Марии Богородицей." },
  { key: "01-31", name: "Прп. Афанасия Сяндемского (Сяндебского), Вологодского", kind: "saint", desc: "Ученик преподобного Александра Свирского . Сподобился быть свидетелем благодатного посещения его учителя Пресвятой Девой Богородицей. Преподобный Афанасий начал свои иноческие подвиги на Валааме, а затем в Свирском монастыре." },
  { key: "01-31", name: "прав. Афанасия Наволоцкого", kind: "saint", desc: "О рождении и воспитании Афанасия Наволоцкого ничего не известно, преподобный пришел из окрестностей Каргополя на реку Вагу и поселился в 3 верстах от Верхоледской слободки, находившейся близ города Шенкурска." },
  { key: "01-31", name: "прп. Маркиана Кирского", kind: "saint", desc: "Прп. Маркиан (IV век) – подвижник, проведший жизнь в строгом пустынном затворе. Его келия по ночам озарялась Божественным светом во время молитв. Со временем он принял двух учеников, но продолжал жить в уединении." },
  { key: "01-31", name: "Сщмч. Михаила Каргополова, пресвитера", kind: "saint", desc: "Священномученик Михаил (Каргополов) служил священником в селе Петровское Ачинского уезда Енисейской губернии. До принятия сана он был офицером казачьих войск." },
  { key: "01-31", name: "сщмч. Евгения Исадского, пресвитера", kind: "saint", desc: "Священник Евгений родился в 1879 году в селе Погост-Преображенский Егорьевского уезда в семье диакона Герасима Исадского. Окончил Рязанскую семинарию и в 1901 году был рукоположен во священника к Петропавловской церкви в селе Маливо Егорьевского уезда (ныне Коломенский район)." },
  { key: "01-31", name: "Владимира Зубковича", kind: "saint", desc: "Священномученик Владимир родился 26 марта 1863 года в селе Смолевичи Борисовского уезда Минской губернии в семье священника Гавриила Зубковича. В 1885 году Владимир окончил Минскую Духовную семинарию и в течение двух лет служил младшим контролером в Минском акцизном управлении." },
  { key: "01-31", name: "Николая Красовского", kind: "saint", desc: "Священномученик Николай родился 7 мая 1876 года в селе Воинова Гора Покровского уезда Владимирской губернии в семье священника Константина Красовского и его супруги Надежды, дочери священника Симеона Малинина, предки которого более столетия служили священниками в этом селе." },
  { key: "01-31", name: "Сергия Лебедева", kind: "saint", desc: "Священномученик Сергий родился 16 сентября 1895 года в семье священника Петра Михайловича Лебедева, служившего в Благовещенской церкви в селе Сальково Подольского уезда Московской губернии." },
  { key: "01-31", name: "Александра Русинова", kind: "saint", desc: "Священномученик Александр Владимирович Русинов (1878 – 1938), протоиерей. Родился в 1878 году в селе Куркино Коломенского уезда Московской губернии [1] в семье священника." },
];
